"""Operator page for the installation-wide collection safety gate."""
from fastapi.responses import HTMLResponse


def collection_safety_setup_page() -> HTMLResponse:
    return HTMLResponse(r'''<!doctype html><html class="nct-shell-loading" lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>NCT - Scope &amp; Safety Setup</title>
<style id="nct-shell-bootstrap">html.nct-shell-loading body{visibility:hidden}</style>
<style>
:root{color-scheme:dark;--bg:#081820;--panel:#10252d;--line:#31515d;--text:#e8f0f2;--muted:#aac0c7;--accent:#2ea8df;--good:#5fd3a0;--warn:#ffd166;--bad:#ff7b72}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.5 system-ui,sans-serif}header{padding:20px 4vw;border-bottom:1px solid var(--line)}main{max-width:1120px;margin:auto;padding:32px}.intro,.panel{border:1px solid var(--line);border-radius:14px;background:var(--panel);padding:22px;margin:0 0 18px}.start{display:inline-block;border:1px solid var(--warn);color:var(--warn);border-radius:999px;padding:3px 9px;font-size:.78rem;font-weight:700;letter-spacing:.04em}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.step{color:var(--accent);font-weight:750;text-transform:uppercase;font-size:.8rem;letter-spacing:.06em}label{display:grid;gap:6px;margin:14px 0;font-weight:650}select,input,textarea,button{font:inherit}select,input,textarea{width:100%;padding:10px 12px;color:var(--text);background:#081820;border:1px solid var(--line);border-radius:8px}textarea{min-height:90px;resize:vertical}button,.button{display:inline-block;border:1px solid var(--accent);background:#123443;color:var(--text);border-radius:8px;padding:9px 13px;font-weight:700;text-decoration:none;cursor:pointer}button.primary{background:#17658a}.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.status{border-left:4px solid var(--warn);padding:12px 14px;background:#0b1d24;margin:14px 0}.status.good{border-color:var(--good)}.status.bad{border-color:var(--bad)}.entry{display:flex;gap:10px;align-items:center;border-top:1px solid var(--line);padding:10px 0}.entry code{flex:1;color:var(--text)}.entry button{border-color:var(--bad);background:#3c2023}.meta{color:var(--muted);font-size:.92rem}.checks{margin:8px 0;padding-left:22px}.empty-review{display:flex;align-items:flex-start;gap:9px;font-weight:500}.empty-review input{width:auto;margin-top:5px}.recorded{border:1px solid var(--line);border-radius:8px;padding:12px 14px;background:#0b1d24;margin:14px 0}.recorded strong{color:var(--good)}@media(max-width:760px){main{padding:18px}.grid{grid-template-columns:1fr}}
</style><script src="/assets/nct-session.js"></script></head><body><header><strong>NCT</strong> · Network Correlation &amp; Triage</header><main><section class="intro"><span class="start" id="startBadge">START HERE</span><h1>Set Network Context and Safety Boundaries</h1><p>Complete this once before planning any Nmap scan or live network-device collection. The selected Network Scope tells NCT which environment the evidence belongs to. Global No-Strike exclusions prevent contact with protected addresses across every active collection path.</p><p class="meta">This setup records context and safety boundaries. It does not grant permission to scan or collect from a device.</p></section>
<div class="grid"><section class="panel"><div class="step">Step 1</div><h2>Choose the active Network Scope</h2><p>Select the one reviewed environment this NCT installation is working in. If you need another scope, create it first.</p><label>Network Scope<select id="scope"><option value="">Choose a scope</option></select></label><a class="button" href="/settings/network-scopes">Manage Network Scopes</a></section>
<section class="panel"><div class="step">Step 2</div><h2>Set Global No-Strike exclusions</h2><p>Add every IPv4 address or CIDR block NCT must never contact. Broad CIDRs are supported, including <code>10.0.0.0/8</code>.</p><label>Add addresses or CIDRs<textarea id="entries" placeholder="10.0.0.0/8&#10;192.0.2.25"></textarea></label><button id="add">Add exclusions</button><div id="noStrikeList" aria-live="polite"></div></section></div>
<section class="panel"><div class="step">Step 3</div><h2>Review and record setup</h2><div id="readiness" class="status">Loading current setup…</div><div id="recordedReview" class="recorded" hidden></div><label id="emptyReviewRow" class="empty-review" hidden><input id="emptyReview" type="checkbox"><span>For this review, I confirm that no Global No-Strike exclusions are currently required.</span></label><label>Reason for this setup review<textarea id="reason" maxlength="500" placeholder="Example: Initial review for the home lab environment"></textarea></label><div class="actions"><button class="primary" id="record">Record reviewed setup</button><span class="meta" id="revision"></span></div><p id="saveStatus" role="status" aria-live="polite"></p></section>
<section class="panel"><h2>What happens next</h2><p>When all checks are current, NCT allows collection planning for evidence tied to this Network Scope. NCT rechecks this decision before network contact. Changing or archiving the scope, or changing Global No-Strike exclusions, makes this review stale until an administrator records it again.</p><p><strong>Uploads and saved-evidence analysis remain available</strong> even when this setup needs review because those actions do not contact a network.</p></section>
<script>(()=>{const $=id=>document.getElementById(id);let state=null,scopes=[];const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));async function api(url,options={}){const response=await fetch(url,{credentials:'same-origin',...options});let data={};try{data=await response.json()}catch(_){}if(!response.ok)throw Error(data.detail||'Request failed');return data}function lines(value){return value.split(/\r?\n|,/).map(item=>item.trim()).filter(Boolean)}function render(){const list=state?.no_strike?.entries||[],review=state?.review;$('noStrikeList').innerHTML=list.length?list.map(item=>`<div class="entry"><code>${esc(item)}</code><button type="button" data-remove="${esc(item)}">Remove</button></div>`).join(''):'<p class="meta">No shared exclusions are recorded.</p>';$('emptyReviewRow').hidden=Boolean(list.length);$('emptyReview').checked=Boolean(!list.length&&state?.ready&&review?.empty_no_strike_reviewed);const missing=state?.missing_checks||[];$('readiness').className='status '+(state?.ready?'good':missing.length?'bad':'');$('readiness').innerHTML=`<strong>${esc(state?.message||'Setup unavailable')}</strong>${missing.length?`<ul class="checks">${missing.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:''}`;$('startBadge').hidden=Boolean(state?.ready);$('revision').textContent=review?`Last recorded by ${review.reviewed_by} · ${new Date(review.reviewed_at).toLocaleString()} · review ${review.revision}`:'No setup review recorded';$('recordedReview').hidden=!review;if(review)$('recordedReview').innerHTML=`<strong>Recorded review ${Number(review.revision)}</strong><br>Scope: ${esc(state?.scope?.label||review.scope_id)}<br>Global No-Strike: ${list.length?`${list.length} recorded exclusion${list.length===1?'':'s'}`:review.empty_no_strike_reviewed?'None required — explicitly reviewed':'Empty list was not confirmed'}<br>Reason: ${esc(review.reason)}<br><span class="meta">Recorded by ${esc(review.reviewed_by)} · ${new Date(review.reviewed_at).toLocaleString()}</span>`;const selected=state?.scope?.scope_id||review?.scope_id||'';if(selected)$('scope').value=selected;document.querySelectorAll('[data-remove]').forEach(button=>button.onclick=()=>removeEntry(button.dataset.remove))}async function load(){[scopes,state]=await Promise.all([api('/api/network-scopes'),api('/api/collection-safety-setup')]);$('scope').innerHTML='<option value="">Choose a scope</option>'+scopes.map(item=>`<option value="${esc(item.scope_id)}" data-version="${item.version}">${esc(item.label)} · version ${item.version}</option>`).join('');render()}async function addEntries(){const entries=lines($('entries').value);if(!entries.length){$('saveStatus').textContent='Enter at least one address or CIDR.';return}try{await api('/api/safety/no-strike',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({entries,changed_by:'page-actor'})});$('entries').value='';$('saveStatus').textContent='Global No-Strike exclusions updated. Record the setup review after checking the full list.';state=await api('/api/collection-safety-setup');render()}catch(error){$('saveStatus').textContent=error.message}}async function removeEntry(entry){if(!confirm(`Remove ${entry} from the installation-wide No-Strike list? The setup review will become stale.`))return;try{const challenge=await api('/api/safety/no-strike/remove-challenge',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify([entry])});await api('/api/safety/no-strike/remove',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({entries:[entry],changed_by:'page-actor',confirmation:challenge.challenge})});$('saveStatus').textContent='Exclusion removed. Review and record the setup again.';state=await api('/api/collection-safety-setup');render()}catch(error){$('saveStatus').textContent=error.message}}async function record(){const option=$('scope').selectedOptions[0],scopeId=$('scope').value;if(!scopeId){$('saveStatus').textContent='Choose a Network Scope.';return}const reason=$('reason').value.trim();if(!reason){$('saveStatus').textContent='Enter a reason for the review.';return}try{state=await api('/api/collection-safety-setup/reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scope_id:scopeId,expected_scope_version:Number(option.dataset.version),expected_no_strike_revision:Number(state.no_strike.revision),empty_no_strike_reviewed:$('emptyReview').checked,reason})});$('saveStatus').textContent='Scope & Safety Setup recorded.';$('reason').value='';render()}catch(error){$('saveStatus').textContent=error.message;state=await api('/api/collection-safety-setup');render()}}$('add').onclick=addEntries;$('record').onclick=record;load().catch(error=>{$('readiness').textContent=error.message;$('readiness').className='status bad'});})();</script></main></body></html>''')
